create or replace function public.ils_professional_assignment_transition_gate(p_assignment_link_id uuid,p_to_status text) returns boolean language plpgsql security definer stable set search_path=public as $$ declare v_link record; v_allowed boolean; begin if auth.uid() is null or p_assignment_link_id is null then return false; end if; select * into v_link from public.ils_professional_work_assignment_links where id=p_assignment_link_id and professional_user_id=auth.uid(); if not found then return false; end if; v_allowed := public.ils_professional_assignment_transition_allowed(v_link.link_status,p_to_status); if not v_allowed then return false; end if; if p_to_status in ('APPROVED','ACTIVE') then if not public.ils_professional_assignment_is_current(v_link.work_item_id,v_link.work_stream,v_link.professional_user_id) then return false; end if; end if; return true; end $$; revoke all on function public.ils_professional_assignment_transition_gate(uuid,text) from public,anon,authenticated; grant execute on function public.ils_professional_assignment_transition_gate(uuid,text) to authenticated; create table if not exists public.ils_professional_assignment_transition_gate_audit (id uuid primary key default gen_random_uuid(),assignment_link_id uuid,professional_user_id uuid,from_status text,to_status text,decision text not null,reason_code text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_transition_gate_audit enable row level security; revoke all on public.ils_professional_assignment_transition_gate_audit from anon,authenticated; create index if not exists idx_ils_assignment_transition_gate_audit_link on public.ils_professional_assignment_transition_gate_audit(assignment_link_id,created_at desc);